/* No external runtime dependencies. Local data is encrypted at rest. */
'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const rp=n=>'Rp'+Number(n||0).toLocaleString('id-ID'),uuid=()=>crypto.randomUUID(),monthNow=()=>today().slice(0,7);
const enc=new TextEncoder(),dec=new TextDecoder(),hex=b=>Array.from(new Uint8Array(b),v=>v.toString(16).padStart(2,'0')).join('');
const unhex=s=>new Uint8Array(s.match(/../g).map(v=>parseInt(v,16)));
const b64=a=>{let s='';for(const x of new Uint8Array(a))s+=String.fromCharCode(x);return btoa(s);};
const unb64=s=>Uint8Array.from(atob(s),x=>x.charCodeAt(0));
let S={user:null,token:null,url:'',base:{},queue:[],tab:'catat',syncing:false,lastSync:null,error:'',filterUser:'Gabungan',month:monthNow(),date:today(),query:'',from:'',to:'',filterAccount:'',editing:null};
let vaultKey=null,vaultSalt=null,releaseLock=null,lockReleased=Promise.resolve(),writer=Promise.resolve(),idleTimer=null,syncPromise=null,toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6000);}
function options(items,value){return items.map(([id,name])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(name)}</option>`).join('');}
function visible(){return KK.overlay(S.base,S.queue);}
function items(kind){return KK.list(visible(),kind);}
function label(kind,id){return (visible()[KK.key(kind,id)]?.data?.name)||'Data lama';}
function storedKey(user=S.user,url=S.url){return 'kk2-vault:'+url+':'+user;}
function cacheExists(user,url){return localStorage.getItem(storedKey(user,url));}
async function derive(password,salt,usage='proof'){
 const material=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits','deriveKey']);
 const params={name:'PBKDF2',salt:unhex(salt),iterations:600000,hash:'SHA-256'};
 return usage==='proof'?hex(await crypto.subtle.deriveBits(params,material,256)):crypto.subtle.deriveKey(params,material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);
}
function passwordOK(p){if(p.length<12||p.length>128)throw Error('Password harus 12–128 karakter. Gunakan frasa yang mudah diingat.');}
async function seal(data,key,salt){const iv=crypto.getRandomValues(new Uint8Array(12));return JSON.stringify({version:2,salt,iv:b64(iv),cipher:b64(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,enc.encode(JSON.stringify(data))))});}
async function openVault(raw,pw){const v=JSON.parse(raw);if(v.version!==2)throw Error('Versi cadangan tidak didukung.');const key=await derive(pw,v.salt,'vault');const data=JSON.parse(dec.decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(v.iv)},key,unb64(v.cipher))));return {data,key,salt:v.salt};}
function stateData(base=S.base,queue=S.queue){return {format:'KK2',version:2,base,queue,lastSync:S.lastSync,user:S.user,url:S.url};}
async function durable(base=S.base,queue=S.queue){
 if(!vaultKey)throw Error('Penyimpanan belum terbuka.');
 const encoded=await seal(stateData(base,queue),vaultKey,vaultSalt);
 try{localStorage.setItem(storedKey(),encoded);}catch(e){throw Error('Penyimpanan perangkat gagal/penuh. Data belum disimpan. Ekspor cadangan dan kosongkan ruang.');}
}
function serialize(fn){const p=writer.then(fn);writer=p.catch(()=>{});return p;}
async function api(action,payload={},url=S.url){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);
 try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,token:S.token,...payload}),redirect:'follow',signal:controller.signal,cache:'no-store'});if(!r.ok)throw Error('Server mengembalikan HTTP '+r.status);const data=await r.json();if(data.code==='CONFLICT')return data;if(!data.ok)throw Error(data.error||'Permintaan gagal.');return data;}
 catch(e){if(e.name==='AbortError')throw Error('Server belum merespons. Perubahan tetap dalam antrean; sinkronkan ulang.');throw e;}finally{clearTimeout(timer);}
}
function checkURL(url){if(!/^https:\/\/script\.google\.com\/macros\/s\/[\w-]+\/exec$/.test(url))throw Error('Gunakan URL deployment Apps Script https://script.google.com/macros/s/…/exec.');}
function validateState(base){if(!base||typeof base!=='object'||Array.isArray(base))throw Error('Data cadangan tidak valid.');for(const [k,e] of Object.entries(base)){if(!KK.kinds.includes(e.kind)||!KK.idOK(e.id)||k!==KK.key(e.kind,e.id)||!Number.isInteger(e.rev)||e.rev<0)throw Error('Struktur data tidak valid.');if(!e.deleted)KK.validate(e.kind,e.data);}}
async function acquire(user,url){
 if(!navigator.locks)throw Error('Browser ini belum mendukung penguncian tab. Gunakan Chrome, Edge, Firefox, atau Safari terbaru.');
 return new Promise((resolve,reject)=>{lockReleased=navigator.locks.request(storedKey(user,url),{ifAvailable:true},async lock=>{
  if(!lock){reject(Error('Akun ini sudah terbuka di tab lain. Kunci tab tersebut terlebih dahulu.'));return;}
  await new Promise(done=>{releaseLock=done;resolve();});
 }).catch(reject);});
}
function renderAuth(){
 let url='';try{url=localStorage.getItem('kk2-url')||localStorage.getItem('sheet_url')||'';}catch(e){}
 $('#app').innerHTML=`<main class="auth"><img class="brand-icon" src="icons/icon-192.png" alt=""><div class="eyebrow" style="margin-top:20px">Ruang keuangan bersama</div><h1>Kas Keluarga</h1><p class="muted" style="margin-top:10px">Catatan rapi. Rencana lebih pasti.</p><section class="card"><h2>Masuk ke keluarga</h2><form id="login"><label>URL Google Apps Script<input name="url" type="url" required value="${esc(url)}" placeholder="https://script.google.com/macros/s/…/exec"></label><label>Pengguna<select name="user">${options([['Abi','Abi'],['Umi','Umi']],'Abi')}</select></label><label>Password<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><label class="check"><input type="checkbox" name="offline">Buka data tersimpan saat offline</label><div id="authError" class="error-text" role="alert"></div><button>Masuk</button></form><details><summary>Aktivasi pengguna pertama kali</summary><p class="muted" style="font-size:12px;margin-bottom:14px">Jalankan siapkanServer di Apps Script, lalu gunakan kunci aktivasi dari log. Masing-masing pengguna membuat password sendiri.</p><form id="register"><label>Pengguna<select name="user">${options([['Abi','Abi'],['Umi','Umi']],'Abi')}</select></label><label>Kunci aktivasi<input name="setupKey" type="password" required autocomplete="off"></label><label>Password baru (minimal 12 karakter)<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><label>Ulangi password<input name="confirm" type="password" required autocomplete="new-password"></label><button class="secondary">Aktifkan pengguna</button></form></details><details><summary>Pemulihan cache perangkat</summary><p class="muted" style="font-size:12px">Jika password berubah pada perangkat lain, ekspor cadangan dengan password lama terlebih dahulu. Tombol ini mengunduh cache terenkripsi lalu menghapus cache akun/URL yang dipilih pada perangkat ini; data server tetap ada.</p><button class="secondary" type="button" id="clearCache" style="margin-top:12px">Cadangkan dan bersihkan cache akun</button></details></section><small>Data pada perangkat dienkripsi. Koneksi pertama memerlukan internet. Sesi terkunci setelah 10 menit tanpa aktivitas.</small></main>`;
 $('#clearCache').onclick=async()=>{let gotLock=false;try{const url=$('#login [name=url]').value.trim(),user=$('#login [name=user]').value;checkURL(url);await acquire(user,url);gotLock=true;const k=storedKey(user,url),raw=localStorage.getItem(k);if(!raw)throw Error('Cache akun tidak ditemukan.');if(!confirm('Cadangkan lalu hapus cache '+user+' di perangkat ini? Perubahan belum terkirim harus dipulihkan dari cadangan.'))return;download('Kas-Keluarga-cache-'+user+'-'+today()+'.kkbackup',raw);const staged=localStorage.getItem(k+':password-change');if(staged)download('Kas-Keluarga-password-baru-'+user+'.kkbackup',staged);localStorage.removeItem(k);localStorage.removeItem(k+':password-change');toast('Cache dicadangkan dan dibersihkan. Masuk online memakai password terbaru.');}catch(e){$('#authError').textContent=e.message;}finally{if(gotLock&&releaseLock){releaseLock();releaseLock=null;await lockReleased;}}};
 $('#login').onsubmit=e=>{e.preventDefault();login(new FormData(e.target),false,e.target);};
 $('#register').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);f.set('url',$('#login [name=url]').value);login(f,true,e.target);};
}
async function login(f,register,form){
 const button=form.querySelector('button');button.disabled=true;$('#authError').textContent='';let acquired=false;
 try{
  if(!crypto.subtle||!window.isSecureContext)throw Error('Buka melalui HTTPS atau localhost, bukan file lokal.');
  const url=String(f.get('url')).trim(),user=String(f.get('user')),pw=String(f.get('password'));checkURL(url);
  if(register){passwordOK(pw);if(pw!==f.get('confirm'))throw Error('Konfirmasi password tidak sama.');}
  await acquire(user,url);acquired=true;
  let raw=cacheExists(user,url);let cache=null;const staged=localStorage.getItem(storedKey(user,url)+':password-change');
  if(raw){try{cache=await openVault(raw,pw);validateState(cache.data.base);}catch(e){if(staged){try{cache=await openVault(staged,pw);validateState(cache.data.base);}catch(err){throw Error('Password tidak membuka data lokal maupun cadangan perubahan password.');}}else throw Error('Password tidak membuka data lokal. Jika berubah di perangkat lain, buka offline memakai password lama dan ekspor cadangan, lalu gunakan pemulihan cache di bawah.');}}
  let result=null;
  if(f.get('offline')){if(!cache)throw Error('Belum ada data offline untuk akun ini. Masuk online terlebih dahulu.');}
  else{
   const challenge=await api('challenge',{user},url);
   if(register){if(!challenge.needsSetup)throw Error('Akun sudah aktif. Gunakan formulir masuk.');const salt=hex(crypto.getRandomValues(new Uint8Array(16)));result=await api('register',{user,salt,proof:await derive(pw,salt),setupKey:String(f.get('setupKey')).trim()},url);}
   else{if(challenge.needsSetup)throw Error('Akun belum aktif. Buka bagian aktivasi.');result=await api('login',{user,proof:await derive(pw,challenge.salt)},url);}
   validateState(result.entities);
  }
  S={...S,user,url,token:result?.token||null,base:cache?.data.base||result.entities,queue:cache?.data.queue||[],lastSync:cache?.data.lastSync||null,error:'',tab:'catat',editing:null};
  vaultSalt=cache?.salt||hex(crypto.getRandomValues(new Uint8Array(16)));vaultKey=cache?.key||await derive(pw,vaultSalt,'vault');
  await durable();if(staged&&result)localStorage.removeItem(storedKey()+':password-change');localStorage.setItem('kk2-url',url);render();touchIdle();if(S.token)sync();
 }catch(e){if(acquired&&releaseLock){releaseLock();releaseLock=null;await lockReleased;}S.user=null;vaultKey=null;$('#authError')&&($('#authError').textContent=e.message);}finally{button.disabled=false;}
}
async function lock(){if(S.credentialBusy){setTimeout(lock,2000);return;}await writer;if(syncPromise)await syncPromise;S={...S,user:null,token:null,base:{},queue:[],editing:null};vaultKey=null;vaultSalt=null;clearTimeout(idleTimer);if(releaseLock){releaseLock();releaseLock=null;await lockReleased;}$('#modal').close();renderAuth();}
function touchIdle(){if(!S.user)return;clearTimeout(idleTimer);idleTimer=setTimeout(lock,10*60000);}
['pointerdown','keydown'].forEach(t=>document.addEventListener(t,touchIdle,{passive:true}));
async function enqueue(kind,data,id=data?.id,deleted=false){
 return serialize(async()=>{
  if(S.credentialBusy)throw Error('Tunggu penggantian password selesai.');if(!deleted){KK.validate(kind,data);KK.relations(kind,data,visible());}
  const key=KK.key(kind,id),baseRev=S.base[key]?.rev||0;
  const op={opId:uuid(),kind,id,baseRev,data:data||null,deleted};
  const q=[...S.queue,op];const next=KK.overlay(S.base,q);
  for(const g of KK.list(next,'goal'))if(KK.saved(next,g.id)<0)throw Error('Penarikan melebihi setoran tujuan tabungan.');
  await durable(S.base,q);S.queue=q;S.error='';renderStatus();
 });
}
async function sync(){
 if(S.credentialBusy)return;if(syncPromise)return syncPromise;if(!S.user||!S.token||!navigator.onLine){renderStatus();return;}
 syncPromise=(async()=>{
 S.syncing=true;S.error='';renderStatus();
 try{
  while(S.queue.length){
   const op=JSON.parse(JSON.stringify(S.queue[0]));const r=await api('mutate',{op});
   if(!r.ok&&r.code==='CONFLICT'){
    await serialize(async()=>{const q=[...S.queue];q[0]={...q[0],conflict:r.current,hasConflict:true};await durable(S.base,q);S.queue=q;});
    throw Error('Ada konflik data. Buka “Selesaikan konflik” sebelum melanjutkan.');
   }
   await serialize(async()=>{
    const base={...S.base,[KK.key(op.kind,op.id)]:r.entity};const q=S.queue.filter(o=>o.opId!==op.opId).map(o=>o.kind===op.kind&&o.id===op.id?{...o,baseRev:r.entity.rev}:o);
    await durable(base,q);S.base=base;S.queue=q;
   });
  }
  const r=await api('read');validateState(r.entities);
  await serialize(async()=>{S.lastSync=new Date().toISOString();await durable(r.entities,S.queue);S.base=r.entities;});
 }catch(e){S.error=e.message;}finally{S.syncing=false;syncPromise=null;renderStatus();if(['bulanan','harian','cari'].includes(S.tab))renderPage();}
 })();return syncPromise;
}
function statusHTML(){
 const pending=S.queue.length;const status=S.syncing?'Menyinkronkan…':S.error?S.error:pending?`${pending} perubahan tersimpan di perangkat, menunggu sinkronisasi`:!S.token?'Mode offline — masuk online untuk mengirim perubahan':S.lastSync?'Tersimpan di Google Sheet':'Tersimpan di perangkat';
 return `<div class="status ${S.error?'error':pending?'pending':''}"><div><strong>${esc(status)}</strong><br><small>${S.lastSync?'Sinkronisasi terakhir '+esc(new Date(S.lastSync).toLocaleString('id-ID')):'Belum ada sinkronisasi'}</small></div><div class="actions">${pending?'<button class="small secondary" data-action="queue">Antrean</button>':''}${S.queue[0]?.hasConflict?'<button class="small danger" data-action="conflict">Selesaikan konflik</button>':''}<button class="small secondary" data-action="sync" ${S.syncing?'disabled':''}>Sinkronkan</button></div></div>`;
}
function renderStatus(){if($('#syncStatus'))$('#syncStatus').innerHTML=statusHTML();}
function render(){
 $('#app').innerHTML=`<main class="wrap"><header class="top"><div class="brand"><img src="icons/icon-192.png" alt=""><div><strong>Kas Keluarga</strong><small>Ruang bersama · ${esc(S.user)}</small></div></div><div class="actions"><button class="secondary" data-action="settings" aria-label="Buka pengaturan">Pengaturan</button><button class="secondary" data-action="lock">Kunci</button></div></header><div id="syncStatus">${statusHTML()}</div><nav aria-label="Menu utama">${[['catat','Catat'],['harian','Harian'],['bulanan','Bulanan'],['cari','Cari']].map(([k,v])=>`<button data-tab="${k}" class="${S.tab===k?'active':''}" ${S.tab===k?'aria-current="page"':''}>${v}</button>`).join('')}</nav><div id="page"></div><footer>Kas Keluarga 2.0 · Pencatat menunjukkan penginput, bukan pemilik uang.</footer></main>`;
 renderPage();
}
function txRow(t){const inflow=t.jenis==='masuk';const isFlow=['masuk','keluar'].includes(t.jenis);const name=isFlow?label('category',t.categoryId):({transfer:'Transfer antarakun',setor:'Setoran tabungan',tarik:'Penarikan tabungan'}[t.jenis]);return `<article class="row"><div class="main"><strong>${esc(name)}${S.queue.some(o=>o.kind==='tx'&&o.id===t.id)?'<span class="badge">Menunggu</span>':''}</strong><small>${esc(t.tanggal)} · Dicatat ${esc(t.oleh)}<br>${esc(label('account',t.accountId))}${!isFlow?' → '+esc(label('account',t.toAccountId)):''}${t.goalId?' · '+esc(label('goal',t.goalId)):''}${t.catatan?'<br>'+esc(t.catatan):''}</small></div><div><div class="amount ${isFlow?(inflow?'in':'out'):''}">${isFlow?(inflow?'+':'−'):''}${rp(t.jumlah)}</div><div class="actions"><button class="small secondary" data-edit="${esc(t.id)}" aria-label="Ubah transaksi ${esc(name)}">Ubah</button><button class="small danger" data-delete="${esc(t.id)}" aria-label="Hapus transaksi ${esc(name)}">Hapus</button></div></div></article>`;}
const rows=txs=>txs.length?txs.sort((a,b)=>b.tanggal.localeCompare(a.tanggal)||b.dibuatPada-a.dibuatPada).map(txRow).join(''):'<div class="empty">Belum ada transaksi pada pilihan ini.</div>';
function renderPage(){
 const p=$('#page');if(!p)return;
 if(S.tab==='catat')renderCatat(p);
 if(S.tab==='harian')renderHarian(p);
 if(S.tab==='bulanan')renderBulanan(p);
 if(S.tab==='cari')renderCari(p);
 if(S.tab==='settings')renderSettings(p);
}
function transactionFields(t={}){
 const typ=t.jenis||'keluar';const cats=items('category').filter(c=>c.type===typ&&(!c.archived||c.id===t.categoryId));const accts=items('account').filter(a=>!a.archived||[t.accountId,t.toAccountId].includes(a.id));
 return `<div class="grid" style="gap:14px"><label>Tanggal<input name="tanggal" type="date" value="${esc(t.tanggal||today())}" required></label><label>Jenis<select name="jenis" id="txType">${options([['keluar','Pengeluaran'],['masuk','Pemasukan'],['transfer','Transfer'],['setor','Setoran tabungan'],['tarik','Penarikan tabungan']],typ)}</select></label></div><label>Nominal (rupiah)<input name="jumlah" type="number" min="1" max="1000000000000" step="1" inputmode="numeric" required value="${t.jumlah||''}" placeholder="Contoh: 150000"></label><div id="txSpecific">${['masuk','keluar'].includes(typ)?`<label>Kategori<select name="categoryId" required>${options(cats.map(c=>[c.id,c.name]),t.categoryId)}</select></label>`:''}${['setor','tarik'].includes(typ)?`<label>Tujuan tabungan<select name="goalId" required>${options(items('goal').filter(g=>!g.archived||g.id===t.goalId).map(g=>[g.id,g.name]),t.goalId)}</select></label>`:''}</div><label>${typ==='masuk'?'Akun penerima':'Akun asal'}<select name="accountId" required>${options(accts.map(a=>[a.id,a.name]),t.accountId)}</select></label>${!['masuk','keluar'].includes(typ)?`<label>Akun tujuan<select name="toAccountId" required>${options(accts.map(a=>[a.id,a.name]),t.toAccountId||accts[1]?.id)}</select></label>`:''}${typ==='keluar'?`<label>Tagihan terkait (opsional)<select name="billId">${options([['','Bukan pembayaran tagihan'],...items('bill').filter(b=>!b.archived||b.id===t.billId).map(b=>[b.id,b.name])],t.billId||'')}</select></label><label>Periode tagihan<input name="billPeriod" type="month" value="${esc(t.billPeriod||(t.tanggal||today()).slice(0,7))}"></label>`:''}<label>Catatan<textarea name="catatan" maxlength="1000" placeholder="Tambahkan keterangan…">${esc(t.catatan||'')}</textarea></label>`;
}
function renderCatat(p){
 const e=visible(),bal=KK.balances(e,today()),total=Object.values(bal).reduce((a,b)=>a+b,0),ts=items('tx'),flow=KK.flow(ts.filter(t=>t.tanggal.slice(0,7)===monthNow()));const bills=items('bill').filter(b=>!b.archived&&KK.billPaid(e,b.id,monthNow())<b.amount);
 p.innerHTML=`<div class="grid"><div><section class="hero"><div class="eyebrow">Saldo gabungan hari ini</div><div class="total">${rp(total)}</div><div class="metrics"><div><small>Masuk bulan ini</small><strong class="in">${rp(flow.masuk)}</strong></div><div><small>Keluar bulan ini</small><strong class="out">${rp(flow.keluar)}</strong></div></div></section>${bills.length?`<div class="notice warn"><b>${bills.length} tagihan belum lunas bulan ini</b>${bills.map(b=>`<div class="split" style="margin:10px 0 0"><span>${esc(b.name)} · sisa ${rp(Math.max(0,b.amount-KK.billPaid(e,b.id,monthNow())))}</span><button class="small secondary" data-pay="${b.id}">Catat bayar</button></div>`).join('')}</div>`:''}<section class="card"><h2>${S.editing?'Ubah transaksi':'Catat transaksi'}</h2><form id="txForm">${transactionFields(S.editing||{})}<div class="error-text" id="formError" role="alert"></div><button>${S.editing?'Simpan perubahan':'Simpan transaksi'}</button>${S.editing?'<button type="button" class="secondary" data-action="cancelEdit">Batal ubah</button>':''}</form></section></div><div><section class="card"><h2>Akun keluarga</h2>${items('account').map(a=>`<div class="row"><div><strong>${esc(a.name)}</strong><small>${a.archived?'Diarsipkan':'Saldo berjalan'}</small></div><strong>${rp(bal[a.id])}</strong></div>`).join('')}</section><section class="card"><h2>Catatan hari ini</h2>${rows(ts.filter(t=>t.tanggal===today()))}</section></div></div>`;
 bindTxForm();
}
function bindTxForm(){
 const f=$('#txForm');$('#txType').onchange=()=>{const obj=Object.fromEntries(new FormData(f));S.editing=S.editing?{...S.editing,...obj}:null;const original=S.editing;const draft={...obj,jumlah:Number(obj.jumlah)||''};f.innerHTML=transactionFields(draft)+'<div class="error-text" id="formError" role="alert"></div><button>Simpan transaksi</button>'+(original?'<button type="button" class="secondary" data-action="cancelEdit">Batal ubah</button>':'');bindTxForm();};
 const bill=f.elements.billId;if(bill)bill.onchange=()=>{const b=items('bill').find(b=>b.id===bill.value);if(b)f.elements.categoryId.value=b.categoryId;};
 const goal=f.elements.goalId;if(goal){goal.onchange=()=>{const g=items('goal').find(g=>g.id===goal.value);if(g){if(f.elements.jenis.value==='setor')f.elements.toAccountId.value=g.accountId;else f.elements.accountId.value=g.accountId;}};goal.onchange();}
 f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('button');btn.disabled=true;try{const d=Object.fromEntries(new FormData(f));d.jumlah=Number(d.jumlah);d.id=S.editing?.id||uuid();d.oleh=S.editing?.oleh||S.user;d.dibuatPada=S.editing?.dibuatPada||Date.now();if(!d.billId){delete d.billId;delete d.billPeriod;}await enqueue('tx',d);S.editing=null;render();toast('Transaksi tersimpan di perangkat.');sync();}catch(e){$('#formError').textContent=e.message;btn.disabled=false;}};
}
